package com.collabspace.service;
import com.collabspace.dto.AuthDtos.*; import com.collabspace.entity.*; import com.collabspace.repository.UserRepository; import com.collabspace.security.JwtService; import lombok.RequiredArgsConstructor; import org.springframework.security.authentication.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor public class AuthService { private final UserRepository users; private final PasswordEncoder encoder; private final JwtService jwt; @Transactional public AuthResponse register(RegisterRequest r){if(users.existsByEmail(r.email().toLowerCase()))throw new IllegalArgumentException("Email already registered");if(users.existsByUsername(r.username()))throw new IllegalArgumentException("Username already taken");User u=User.builder().username(r.username().trim()).email(r.email().trim().toLowerCase()).password(encoder.encode(r.password())).build();users.save(u);return new AuthResponse(jwt.generateToken(u.getEmail()),toDto(u));} public AuthResponse login(LoginRequest r){User u=users.findByEmail(r.email().toLowerCase()).orElseThrow(()->new BadCredentialsException("Invalid email or password"));if(!encoder.matches(r.password(),u.getPassword()))throw new BadCredentialsException("Invalid email or password");return new AuthResponse(jwt.generateToken(u.getEmail()),toDto(u));} public UserResponse toDto(User u){return new UserResponse(u.getId(),u.getUsername(),u.getEmail(),u.getProfilePicture(),u.getStatus().name(),u.getLastSeen(),u.getRole().name());} }